<h1>Đặt mật khẩu mới</h1>
<?php if(!$resetToken): ?><p class="alert alert-danger">Liên kết không hợp lệ.</p><a class="btn btn-primary" href="<?= e(url('/forgot-password')) ?>">Yêu cầu liên kết mới</a>
